) VALUES (
    'planica-venue-guide',
    '{"en": "Planica: Where Humans Learn to Fly", "de": "Planica: Wo Menschen fliegen lernen", "fr": "Planica : Où les hommes apprennent à voler", "it": "Planica: Dove gli uomini imparano a volare", "es": "Planica: Donde los humanos aprenden a volar", "pt": "Planica: Onde os humanos aprendem a voar", "nl": "Planica: Waar mensen leren vliegen", "ar": "بلانيكا: حيث يتعلم البشر الطيران", "ja": "プラニツァ：人間が飛ぶことを学ぶ場所", "zh": "Planica: Renlei Xuexi Feixiang de Difang", "ko": "플라니차: 인간이 나는 법을 배우는 곳"}'::jsonb,
    '{"en": "The ski flying hill at Planica is where the world''s longest jumps take place. This Slovenian venue pushes the boundaries of what''s possible in ski jumping.", "de": "Die Skiflugschanze in Planica ist der Ort, wo die längsten Sprünge der Welt stattfinden.", "fr": "Le tremplin de vol à ski de Planica est l''endroit où les sauts les plus longs du monde ont lieu.", "it": "Il trampolino di volo con gli sci di Planica è dove avvengono i salti più lunghi del mondo.", "es": "El trampolín de vuelo de esquí en Planica es donde tienen lugar los saltos más largos del mundo.", "pt": "A rampa de voo de esqui em Planica é onde os saltos mais longos do mundo acontecem.", "nl": "De skivliegheuvel in Planica is waar ''s werelds langste sprongen plaatsvinden.", "ar": "تل التزلج الطائر في بلانيكا هو المكان الذي تحدث فيه أطول القفزات في العالم", "ja": "プラニツァのスキーフライングヒルは、世界最長のジャンプが行われる場所です。", "zh": "Planica de huaxue feixing shanpo shi shijie shang zuichang de tiaoyue fasheng de difang.", "ko": "플라니차의 스키플라잉 힐은 세계에서 가장 긴 점프가 이루어지는 곳입니다."}'::jsonb,
    '{"en": "<p>Planica is where <a href=\"/ski-jumping-guide/\">ski jumping</a> transforms into ski flying. The giant hill in this Slovenian valley enables jumps of over 240 meters, pushing athletes to the absolute limits of the sport.</p><h2>Ski Flying</h2><p>Ski flying differs from normal ski jumping primarily in scale. The larger hill allows athletes to reach greater speeds and soar further than on any normal jumping hill. Jumps routinely exceed 230 meters, with the world record pushing past 250 meters.</p><p>The experience of watching ski flying is unlike anything else in winter sports. Athletes genuinely appear to fly, hanging in the air for several seconds before landing.</p><h2>World Records</h2><p>Planica has been the site of numerous world records throughout ski jumping history. The venue''s favorable aerodynamics and massive hill dimensions create ideal conditions for the longest jumps ever recorded.</p><p>Champions like <a href=\"/stefan-kraft-profile/\">Stefan Kraft</a>, <a href=\"/ryoyu-kobayashi-profile/\">Ryoyu Kobayashi</a>, and <a href=\"/halvor-granerud-profile/\">Halvor Egner Granerud</a> have soared down this legendary hill.</p><h2>The Nordic Center</h2><p>Planica also hosts cross-country skiing events, making it a complete Nordic skiing venue. The trails through the Julian Alps provide spectacular racing terrain.</p><h2>Slovenian Passion</h2><p>Slovenia punches far above its weight in ski jumping, and Planica is the heart of this passion. The <a href=\"/nika-prevc-profile/\">Prevc family</a> and other Slovenian jumpers enjoy tremendous home support here.</p><h2>Location</h2><p>Planica sits in the Tarentaise Valley near the border with Austria and Italy. The Julian Alps provide a dramatic backdrop for the world''s most spectacular jumps.</p><h2>Getting There</h2><p>The venue is accessible from Ljubljana Airport (about 80 km) or Klagenfurt Airport in Austria. The mountain scenery along the way is spectacular.</p>", "de": "<p>Planica ist der Ort, wo <a href=\"/ski-jumping-guide/\">Skisprung</a> zum Skifliegen wird. Die Riesenschanze in diesem slowenischen Tal ermöglicht Sprünge von über 240 Metern.</p><h2>Skifliegen</h2><p>Skifliegen unterscheidet sich vom normalen Skisprung hauptsächlich in der Größenordnung. Die größere Schanze ermöglicht Athleten, höhere Geschwindigkeiten zu erreichen und weiter zu fliegen.</p><h2>Weltrekorde</h2><p>Planica war Schauplatz zahlreicher Weltrekorde. Champions wie <a href=\"/stefan-kraft-profile/\">Stefan Kraft</a> und <a href=\"/ryoyu-kobayashi-profile/\">Ryoyu Kobayashi</a> sind diese legendäre Schanze hinuntergeflogen.</p><h2>Slowenische Leidenschaft</h2><p>Die <a href=\"/nika-prevc-profile/\">Familie Prevc</a> und andere slowenische Springer genießen hier enormen Heimvorteil.</p>", "fr": "<p>Planica est l''endroit où le <a href=\"/ski-jumping-guide/\">saut à ski</a> se transforme en vol à ski. Le grand tremplin dans cette vallée slovène permet des sauts de plus de 240 mètres.</p><h2>Vol à ski</h2><p>Le vol à ski diffère du saut à ski normal principalement par l''échelle. Le plus grand tremplin permet aux athlètes d''atteindre des vitesses plus élevées.</p><h2>Records du monde</h2><p>Des champions comme <a href=\"/stefan-kraft-profile/\">Stefan Kraft</a> et <a href=\"/ryoyu-kobayashi-profile/\">Ryoyu Kobayashi</a> ont volé sur ce tremplin légendaire.</p>", "it": "<p>Planica è dove il <a href=\"/ski-jumping-guide/\">salto con gli sci</a> si trasforma in volo con gli sci. Il grande trampolino in questa valle slovena permette salti di oltre 240 metri.</p><h2>Volo con gli sci</h2><p>Il volo con gli sci differisce dal normale salto principalmente per la scala. Il trampolino più grande permette agli atleti di raggiungere velocità maggiori.</p><h2>Record mondiali</h2><p>Campioni come <a href=\"/stefan-kraft-profile/\">Stefan Kraft</a> hanno volato su questo trampolino leggendario.</p>", "es": "<p>Planica es donde el <a href=\"/ski-jumping-guide/\">salto de esquí</a> se transforma en vuelo de esquí. El gran trampolín en este valle esloveno permite saltos de más de 240 metros.</p><h2>Vuelo de esquí</h2><p>El vuelo de esquí difiere del salto de esquí normal principalmente en escala.</p>", "pt": "<p>Planica é onde o <a href=\"/ski-jumping-guide/\">salto de esqui</a> se transforma em voo de esqui. A grande rampa neste vale esloveno permite saltos de mais de 240 metros.</p><h2>Voo de esqui</h2><p>O voo de esqui difere do salto de esqui normal principalmente em escala.</p>", "nl": "<p>Planica is waar <a href=\"/ski-jumping-guide/\">schansspringen</a> verandert in skiën vliegen. De grote schans in deze Sloveense vallei maakt sprongen van meer dan 240 meter mogelijk.</p><h2>Skiën vliegen</h2><p>Skiën vliegen verschilt van normaal schansspringen voornamelijk in schaal.</p>", "ar": "<p>بلانيكا هي المكان الذي يتحول فيه <a href=\"/ski-jumping-guide/\">القفز على الجليد</a> إلى التزلج الطائر. يتيح التل العملاق في هذا الوادي السلوفيني قفزات تتجاوز 240 متراً.</p><h2>التزلج الطائر</h2><p>يختلف التزلج الطائر عن القفز العادي بشكل رئيسي في الحجم.</p>", "ja": "<p>プラニツァは、<a href=\"/ski-jumping-guide/\">スキージャンプ</a>がスキーフライングに変わる場所です。このスロベニアの谷にある巨大な丘は、240メートル以上のジャンプを可能にします。</p><h2>スキーフライング</h2><p>スキーフライングは、主にスケールで通常のスキージャンプと異なります。</p>", "zh": "<p>Planica shi <a href=\"/ski-jumping-guide/\">huaxue tiaoyue</a> zhuanbian wei huaxue feixing de difang. Zhe ge Siluowenniya shangu de juda shanpo keyi shixian chaoguo 240 mi de tiaoyue.</p><h2>Huaxue feixing</h2><p>Huaxue feixing yu putong huaxue tiaoyue zhuyao zai guimo shang you suo butong.</p>", "ko": "<p>플라니차는 <a href=\"/ski-jumping-guide/\">스키점프</a>가 스키플라잉으로 변하는 곳입니다. 이 슬로베니아 계곡의 거대한 언덕은 240미터 이상의 점프를 가능하게 합니다.</p><h2>스키플라잉</h2><p>스키플라잉은 주로 규모에서 일반 스키점프와 다릅니다.</p>"}'::jsonb,
    'venue-guide',
    'SJ',
    '{"en": "Planica venue guide - Slovenia''s legendary ski flying hill where world records are set and jumps exceed 240 meters in the Julian Alps.", "de": "Planica Venue Guide - Sloweniens legendäre Skiflugschanze, wo Weltrekorde aufgestellt werden.", "fr": "Guide du site de Planica - Le légendaire tremplin de vol à ski slovène où des records du monde sont établis.", "it": "Guida alla sede di Planica - Il leggendario trampolino di volo con gli sci sloveno dove vengono stabiliti record mondiali.", "es": "Guía del lugar de Planica - El legendario trampolín de vuelo de esquí esloveno donde se establecen récords mundiales.", "pt": "Guia do local de Planica - A lendária rampa de voo de esqui eslovena onde recordes mundiais são estabelecidos.", "nl": "Planica locatiegids - Slovenië''s legendarische skiën vliegheuvel waar wereldrecords worden gevestigd.", "ar": "دليل موقع بلانيكا - تل التزلج الطائر الأسطوري في سلوفينيا حيث تسجل الأرقام القياسية العالمية", "ja": "プラニツァ会場ガイド - 世界記録が樹立されるスロベニアの伝説的なスキーフライングヒル", "zh": "Planica changguan zhinan - Siluowenniya de chuanqi huaxue feixing shanpo, shijie jilu zai zheli dansheng", "ko": "플라니차 경기장 가이드 - 세계 기록이 수립되는 슬로베니아의 전설적인 스키플라잉 힐"}'::jsonb,
    'published',
    NOW(),
    'evergreen'
) ON CONFLICT (slug) DO UPDATE SET
